-- Initial public-reference seed for the requested Caterpillar engine families.
-- These are searchable references, not OEM fitment guarantees or inventory records.
on conflict (part_number) do update set
  name=excluded.name,
  engine_models=excluded.engine_models,
  technical_group=excluded.technical_group,
  source_name=excluded.source_name,
  source_url=excluded.source_url,
  source_note=excluded.source_note,
  verification_status='REFERENCE',
  updated_at=now();
